"use strict";(self.webpackChunk=self.webpackChunk||[]).push([[4838],{24838:function(e){e.exports=JSON.parse('{"labels":{"downloadPdf":"Download PDF","keyReferences":"Key references","imageCreditPrefix":"Image source:","faqTitle":"Common questions","shareWhatsApp":"WhatsApp","copyToClipboard":"Copy","copied":"Copied","printSection":"Print","aiSummaryFab":"AI Summary","textSize":"Text size","decreaseTextSize":"A-","increaseTextSize":"A+","wordCount":"Word count","readTime":"Read time"},"hero":{"arabic":"بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ","title":"The complete Hajj & Umrah guide you actually need.","subtitle":"A clear, source-led Hajj and Umrah guide built around the core Hajj & Umrah, common errors, official health requirements, and the references pilgrims return to most.","primaryButton":{"label":"Begin with Hajj essentials","target":"basics"},"secondaryButton":{"label":"Start with Umrah","target":"umrah"},"trustItems":[{"title":"Primary texts","text":"Core verses and hadith are surfaced directly in the guide."},{"title":"Official travel guidance","text":"Nusuk and Saudi MOH requirements are included and separated from general reminders."},{"title":"Focused structure","text":"Fewer downloads, clearer tools, and less visual clutter."}]},"heroImage":{"src":"https://images.pexels.com/photos/13459175/pexels-photo-13459175.jpeg","alt":"A calm mosque and courtyard scene suited to worship and reflection"},"sectionImages":{"basics":{"src":"https://images.pexels.com/photos/28209449/pexels-photo-28209449.jpeg","alt":"Pilgrims gathered for worship near the Sacred Mosque","credit":"Pexels"},"umrah":{"src":"https://images.pexels.com/photos/13459175/pexels-photo-13459175.jpeg","alt":"Mosque and courtyard scene suited to worship and reflection","credit":"Pexels"},"hajj":{"src":"https://images.pexels.com/photos/12662176/pexels-photo-12662176.jpeg","alt":"Large gathering of worshippers in congregational prayer","credit":"Pexels"},"mistakes":{"src":"https://images.pexels.com/photos/19657349/pexels-photo-19657349.jpeg","alt":"Worshippers praying inside a mosque","credit":"Pexels"},"health":{"src":"https://images.pexels.com/photos/28209449/pexels-photo-28209449.jpeg","alt":"Pilgrims resting and moving carefully in a sacred setting","credit":"Pexels"},"rules":{"src":"https://images.pexels.com/photos/13459175/pexels-photo-13459175.jpeg","alt":"Mosque architecture and calm prayer environment","credit":"Pexels"},"spiritual":{"src":"https://images.pexels.com/photos/19657349/pexels-photo-19657349.jpeg","alt":"Interior mosque scene suitable to reflection and worship","credit":"Pexels"},"postHajj":{"src":"https://images.pexels.com/photos/12662176/pexels-photo-12662176.jpeg","alt":"Congregational prayer after a gathering of worshippers","credit":"Pexels"}},"guidesSection":{"eyebrow":"Downloads","title":"Essential PDF guides","description":"These downloads point to authoritative guides from trusted Islamic sources and official Saudi health requirements."},"pdfGuides":[{"label":"Comprehensive manual","title":"How to perform the manasik of Hajj and Umrah","desc":"Detailed instructional manual by Shaykh Muhammad ibn Sālih al-\'Uthaymīn, a renowned Islamic scholar.","url":"https://d1.islamhouse.com/data/en/ih_books/single/en-dalil-98.pdf","filename":"manasik-of-hajj-and-umrah-al-uthaymeen.pdf"},{"label":"Step-by-step guide","title":"Hajj and Umrah step by step","desc":"A practical manasik guide prepared by the Agency of Islamic Enlightenment in Hajj.","url":"https://d1.islamhouse.com/data/en/ih_books/single2/en-hajj-umrah.pdf","filename":"hajj-umrah-step-by-step.pdf"},{"label":"Official health PDF","title":"Saudi Hajj health requirements 1447H / 2026","desc":"Official Ministry of Health requirements and recommendations. Verify with the live MOH website before travel.","url":"https://www.moh.gov.sa/HealthAwareness/Pilgrims-Health/Documents/Hajj-Health-Requirements-English-language.pdf","filename":"saudi-hajj-health-requirements-1447H-2026.pdf"}],"sections":{"basics":{"eyebrow":"Chapter I","title":"Foundations before the journey","description":"Learn the obligation, the categories of Hajj, and the difference between foundational rulings and personal cases that require a scholar."},"umrah":{"eyebrow":"Chapter II","title":"Umrah step by step","description":"The Umrah sequence is short, but errors usually happen through haste, crowd pressure, or uncertainty at the miqat and during tawaf.","conclusion":{"title":"After Umrah","text":"When the hair is trimmed or shaved, Ihram ends. For Tamattu\', the pilgrim remains out of Ihram until entering Ihram again for Hajj on the 8th of Dhul-Hijjah."}},"hajj":{"eyebrow":"Chapter III","title":"The major days of Hajj","description":"The order of the days matters, but the greatest misunderstanding is forgetting that Arafah is the center of the pilgrimage.","farewell":{"arabic":"طواف الوداع","title":"Tawaf al-Wada (Farewell Tawaf)","text":"Before leaving Makkah, the pilgrim makes a final tawaf unless exempted by a recognized reason. Keep the ending dignified and avoid turning it into a rushed photo stop.","reference":"Reference: Sahih Muslim 1327"}},"mistakes":{"eyebrow":"Chapter IV","title":"Common errors to avoid","description":"These are recurring problems that do not come from lack of sincerity, but from poor preparation, pressure, and imitation without knowledge."},"health":{"eyebrow":"Chapter V","title":"Health, safety, and readiness","description":"Physical ability and official health requirements are part of real-world Hajj preparation. Recheck them close to travel because they can change.","note":"The Ministry of Health requires the meningococcal vaccine for all pilgrims. The seasonal flu vaccine and COVID-19 vaccine are recommended."},"rules":{"eyebrow":"Chapter VI","title":"Ihram rules and etiquette","description":"Know the difference between what remains permitted, what is prohibited, and what should be taken to a scholar when an error happens.","permissibleTitle":"Permissible acts","prohibitedTitle":"Prohibited acts","note":"If an error happened because of illness, forgetfulness, or necessity, do not improvise the ruling. Ask a qualified scholar about validity, fidyah, and what must be repeated."},"spiritual":{"eyebrow":"Chapter VII","title":"Spiritual preparation","description":"The outward manasik are stronger when repentance, humility, patience, and learning have already started before travel."},"shorts":{"eyebrow":"Supplementary Media","title":"Short visual refreshers","description":"These short videos are supplementary visual refreshers only. They are not the standard for legal rulings. Keep the Qur\'an, hadith, and the PDF guides below above any short clip."},"resources":{"eyebrow":"Chapter VIII","title":"Key references and official resources","description":"The content in this guide is retrieved from five trusted Islamic sources only: Quran.com, Sunnah.com, IslamQA, the Nusuk Platform, and the Saudi Ministry of Health."},"postHajj":{"eyebrow":"Closing","title":"Returning home with acceptance in mind","description":"The journey is not measured by photographs or stories, but by repentance, steadier prayer, better conduct, and a sincere hope that Allah accepted it."},"summary":{"eyebrow":"AI summary","title":"A concise end summary","description":"Use this as a fast recap after reading the full guide, not as a replacement for the primary texts, the PDF guides, or a scholar in personal cases."}},"basicsCards":[{"num":"01","title":"Hajj is obligatory for the one who is able","desc":"The obligation is tied to ability: physical capacity, financial capacity, and a safe route to the pilgrimage.","note":"Reference: Qur\'an 3:97."},{"num":"02","title":"Umrah is not casual travel","desc":"The Qur\'an joins Hajj and Umrah in one verse. It is a legislated act of worship, not tourism.","note":"Reference: Qur\'an 2:196."},{"num":"03","title":"Accepted Hajj brings immense reward","desc":"The Prophet ﷺ taught that an accepted Hajj has no reward except Paradise, and one Umrah to the next expiates what came between them.","note":"Reference: Sunan an-Nasa\'i 2622."},{"num":"04","title":"Learning the manasik is part of the obligation","desc":"A pilgrim should not rely on crowd movement alone. Study before travel and ask when the issue affects validity or fidyah.","note":"Reference: Sunan an-Nasa\'i 3062."}],"hajjTypes":[{"title":"Tamattu\'","desc":"Perform Umrah in the months of Hajj, leave Ihram, then re-enter Ihram for Hajj on the 8th of Dhul-Hijjah.","note":"Often the clearest path for many first-time pilgrims."},{"title":"Qiran","desc":"Enter Ihram for Umrah and Hajj together and remain in Ihram until the major manasik are completed.","note":"Keeps the pilgrim in Ihram longer than Tamattu\'."},{"title":"Ifrad","desc":"Enter Ihram for Hajj alone without combining Umrah into the same Ihram.","note":"The practical choice depends on circumstances, group planning, and fiqh guidance."}],"umrahSteps":[{"num":"01","title":"Enter Ihram at the miqat","desc":"Make intention and begin Talbiyah at or before the appointed miqat. Do not cross the miqat without Ihram.","tip":"Prepare clothing and intention before reaching the boundary.","ref":"Reference: Sahih al-Bukhari 1524."},{"num":"02","title":"Perform Tawaf with calmness","desc":"Circle the Kaaba seven times, beginning from the Black Stone area. The purpose is worship, not speed or crowd aggression.","tip":"If reaching the Black Stone is difficult, pointing from a distance is sufficient. Do not harm others.","ref":"Reference: The instruction to learn the manasik in Sunan an-Nasa\'i 3062."},{"num":"03","title":"Complete Sa\'i between Safa and Marwah","desc":"Walk the required lengths between Safa and Marwah. The Qur\'an names them among the symbols of Allah.","tip":"Keep your dua and dhikr steady even when the space is crowded.","ref":"Reference: Qur\'an 2:158."},{"num":"04","title":"Trim or shave the hair","desc":"Men shave or shorten the hair; women cut a small amount from the ends. This ends the state of Ihram for Umrah.","tip":"This is the closing act of the Umrah.","ref":"Reference: Established Prophetic practice in the manasik."}],"hajjDays":[{"date":"8 Dhul-Hijjah","title":"Mina","desc":"Pilgrims go to Mina and spend the day and night there in prayer and preparation. Tamattu\' pilgrims enter Ihram for Hajj on this day.","reminder":"Use the day to settle your mind before Arafah.","ref":"Reference: The Farewell Pilgrimage sequence in the hadith corpus."},{"date":"9 Dhul-Hijjah","title":"Arafah","desc":"Standing at Arafah is the central pillar of Hajj. The pilgrim remains within the boundaries of Arafah until sunset in repentance and supplication.","reminder":"Missing Arafah is not a small error. It is the defining station of Hajj.","ref":"Reference: \'Hajj is Arafah\' in Sunan Ibn Majah 3015."},{"date":"Night of 10 Dhul-Hijjah","title":"Muzdalifah","desc":"After sunset, pilgrims move to Muzdalifah, combine Maghrib and Isha there, rest, and prepare for the next day.","reminder":"Stay with your group safely and keep movement orderly.","ref":"Reference: The Farewell Pilgrimage sequence in the hadith corpus."},{"date":"10 Dhul-Hijjah","title":"Stoning, sacrifice, shaving, and Tawaf al-Ifadah","desc":"Pilgrims stone Jamrat al-Aqabah, arrange sacrifice, shave or trim the hair, and perform Tawaf al-Ifadah.","reminder":"Some ordering concessions exist in the Sunnah.","ref":"Reference: Qur\'an 2:196 and the Prophetic manasik sequence."},{"date":"11 to 13 Dhul-Hijjah","title":"Days of Tashriq","desc":"The pilgrim stays in Mina and stones the three Jamarat on the appointed days.","reminder":"The Qur\'an allows leaving after two days or staying for a third.","ref":"Reference: Qur\'an 2:203."}],"commonMistakes":[{"title":"Crossing the miqat without entering Ihram","desc":"This is a common practical error for travellers who are distracted or unprepared.","note":"Ask a scholar promptly about how to rectify this."},{"title":"Harming others during the manasik","desc":"Pushing and elbowing at the Black Stone area is not devotion. Harming believers is prohibited while kissing the Black Stone is Sunnah.","note":"Preserving the dignity of Muslims is obligatory."},{"title":"Copying actions without knowing what is essential","desc":"Many pilgrims imitate others without knowing whether an act is a pillar, a duty, or a recommended Sunnah.","note":"Use the guides and hadith anchors on this page instead of crowd imitation."},{"title":"Assuming every violation invalidates the pilgrimage","desc":"Some errors require repentance, some require fidyah, and some affect validity more seriously than others.","note":"This is exactly where qualified scholarly advice becomes necessary."}],"healthReadiness":[{"title":"Official readiness checks","items":["The meningococcal vaccine is mandatory for all pilgrims. The seasonal flu and COVID-19 vaccines are recommended.","Pilgrims must be free from infectious diseases and serious chronic conditions such as chronic kidney failure, chronic heart failure, and active cancer.","Review whether age, pregnancy, severe illness, or chronic conditions affect your ability to travel.","Keep official booking, visa, and identification records organized before departure."]},{"title":"On-the-ground practical care","items":["Hydrate consistently and avoid leaving basic fatigue or heat stress untreated.","Use unscented hygiene items while in Ihram.","Carry only what you can realistically manage in crowds and long walks.","If you are medically vulnerable, speak to your doctor and your scholar before travel."]}],"rules":{"permissible":["Using an umbrella, belt, bag, watch, glasses, and shade.","Bathing and washing with unscented products when needed.","Seeking medical care, rest, and crowd safety.","Reciting Qur\'an, making dua, and helping fellow pilgrims."],"prohibited":["Applying perfume after entering Ihram.","Cutting hair or trimming nails without a recognized excuse and ruling.","Marital relations and conduct leading directly to them.","For men: stitched regular clothing and covering the head.","For women: treating the niqab and gloves as Ihram wear.","Hunting land game while in the sacred state."]},"spiritualPrep":[{"step":"01","title":"Repair wrongs before travel","desc":"Return what belongs to people, settle what you can, and ask forgiveness where you have harmed others.","ref":"A sacred journey should not begin carelessly with neglected rights."},{"step":"02","title":"Learn the manasik before the crowd teaches you badly","desc":"Study the order, the common errors, and the places where you must stop and ask a scholar.","ref":"Reference: \'Learn your manasik from me\' in Sunan an-Nasa\'i 3062."},{"step":"03","title":"Train for patience","desc":"Crowds, heat, waiting, and exhaustion are part of the test. The heart should prepare for restraint before the body arrives there.","ref":"Accepted Hajj is tied to upright conduct, not just outward movement."},{"step":"04","title":"Keep the intention simple","desc":"Do not turn pilgrimage into a performance, travel trophy, or social showcase. Intend worship, repentance, and acceptance.","ref":"Reference: Qur\'an 2:127 as a model dua for acceptance."}],"shorts":[{"id":"HfUhWfYsnsA","channel":"Tajweed Online","title":"Step by step guide on how to perform Umrah","note":"Useful as a visual refresher for sequence. Check fiqh details against the PDF guides and textual references."},{"id":"xIgK2ahrXL8","channel":"Brief visual guide","title":"How to perform Umrah step by step","note":"Included as a short visual walkthrough, not as an independent legal authority."},{"id":"nsns8wfR-nE","channel":"English reminder clip","title":"These 7 things are forbidden in Ihram","note":"Useful as a quick English refresher on common Ihram restrictions. Keep the written guide and scholarly references above short clips."}],"resources":[{"label":"Official Saudi government","title":"Nusuk Platform","authority":"Official Saudi government","desc":"Official Saudi government platform used for Hajj and Umrah planning, permits, visas, and provider information.","url":"https://www.nusuk.sa/en","display":"Official Saudi government"},{"label":"Official health authority","title":"Saudi Ministry of Health - Pilgrim\'s Health","authority":"Official health authority","desc":"Official health authority for pilgrim vaccination rules, health requirements, and seasonal medical guidance.","url":"https://www.moh.gov.sa/en/HealthAwareness/Pilgrims-Health/Pages/default.aspx","display":"Official health authority"},{"label":"Islamic Q&A","title":"IslamQA","authority":"Islamic Q&A","desc":"Islamic question-and-answer reference used for issue-based explanations grounded in Qur\'an and Sunnah.","url":"https://islamqa.info/en","display":"Islamic Q&A"},{"label":"Hadith Reference","title":"Sunnah.com","authority":"Hadith reference","desc":"Primary hadith reference used for the narrations cited across the Hajj and Umrah guidance in this guide.","url":"https://sunnah.com","display":"Hadith reference"},{"label":"Qur\'anic Reference","title":"Quran.com","authority":"Qur\'anic reference","desc":"Primary Qur\'anic reference used for the verses cited throughout the guide.","url":"https://quran.com","display":"Qur\'anic reference"}],"faqs":[{"q":"What if I miss standing at Arafah?","a":"Standing at Arafah is central to Hajj. A pilgrim who misses it faces a serious validity issue and should seek immediate scholarly guidance.","ref":"Reference: \'Hajj is Arafah\' in Sunan Ibn Majah 3015."},{"q":"Can I leave Mina after two days?","a":"Yes. The Qur\'an allows departure after two days of the appointed days or staying longer when done properly.","ref":"Reference: Qur\'an 2:203."},{"q":"Are the short videos enough to learn the manasik?","a":"No. They can help visualize the sequence, but should not replace the Qur\'an, hadith, trusted scholars, and structured written guides.","ref":"Use the short videos only as supplementary refreshers."},{"q":"Where should I verify health and travel rules near departure?","a":"Check Nusuk and the Saudi Ministry of Health close to your travel date. Do not rely on old screenshots or group messages.","ref":"Operational guidance can change from season to season."}],"postHajjSteps":[{"num":"01","title":"Ask for acceptance, not praise","desc":"The right response after worship is humility and dua that Allah accepted it.","tip":"Keep the dua of acceptance on your tongue.","ref":"Reference: Qur\'an 2:127."},{"num":"02","title":"Protect the obligations first","desc":"The strongest sign of benefit is steadier prayer, better honesty, and more guarded speech when you return.","tip":"Start with salah, family rights, and daily dhikr.","ref":"Accepted Hajj should leave a trace in conduct."},{"num":"03","title":"Carry the manners of pilgrimage home","desc":"Patience, gentleness, and restraint in crowded sacred places should not disappear at the airport.","tip":"Bring the softened character home, not just souvenirs and stories.","ref":"Reference: Sunan an-Nasa\'i 2622 for the reward of accepted Hajj."}],"summarySection":{"kicker":"AI summary","title":"The page in one clear recap","intro":"This guide starts with the obligation of Hajj, then walks through Umrah, the major days of Hajj, common errors, health readiness, Ihram rules, spiritual preparation, and what should remain after the journey.","points":["Hajj is tied to ability, and serious personal cases still need a qualified scholar.","Arafah is the central station of Hajj. Tawaf, Sa\'i, and the order of the manasik must be learned before travel.","Crowd pressure, health neglect, and imitation without knowledge are among the most common causes of errors.","Official planning through Nusuk and health checks through the Saudi Ministry of Health should be verified close to departure.","The strongest sign of benefit after Hajj or Umrah is better worship, steadier character, and sincere hope for acceptance."],"footer":"Read the full sections for detail, then return to this recap for the essentials."},"sectionReferences":{"basics":[{"title":"Qur\'an 3:97","url":"https://quran.com/3/97"},{"title":"Qur\'an 2:196","url":"https://quran.com/2/196"},{"title":"Sunan an-Nasa\'i 2622","url":"https://sunnah.com/nasai:2622"},{"title":"Sunan an-Nasa\'i 3062","url":"https://sunnah.com/nasai:3062"}],"umrah":[{"title":"Sahih al-Bukhari 1524","url":"https://sunnah.com/bukhari:1524"},{"title":"Qur\'an 2:158","url":"https://quran.com/2/158"},{"title":"Sunan an-Nasa\'i 3062","url":"https://sunnah.com/nasai:3062"}],"hajj":[{"title":"Sunan Ibn Majah 3015","url":"https://sunnah.com/ibnmajah:3015"},{"title":"Qur\'an 2:196","url":"https://quran.com/2/196"},{"title":"Qur\'an 2:203","url":"https://quran.com/2/203"},{"title":"Sahih Muslim 1327","url":"https://sunnah.com/muslim:1327"}],"mistakes":[{"title":"Sunan an-Nasa\'i 3062","url":"https://sunnah.com/nasai:3062"}],"health":[{"title":"Saudi MOH pilgrim health page","url":"https://www.moh.gov.sa/en/HealthAwareness/Pilgrims-Health/Pages/default.aspx"},{"title":"Saudi Hajj Health Requirements PDF","url":"https://www.moh.gov.sa/HealthAwareness/Pilgrims-Health/Documents/Hajj-Health-Requirements-English-language.pdf"}],"rules":[{"title":"Qur\'an 2:196","url":"https://quran.com/2/196"},{"title":"Sunan an-Nasa\'i 3062","url":"https://sunnah.com/nasai:3062"}],"spiritual":[{"title":"Sunan an-Nasa\'i 3062","url":"https://sunnah.com/nasai:3062"},{"title":"Sunan an-Nasa\'i 2622","url":"https://sunnah.com/nasai:2622"},{"title":"Qur\'an 2:127","url":"https://quran.com/2/127"}]},"disclaimer":{"title":"Scope of this page","text":"This guide aims to stay close to primary texts, established instructional guides, and official Saudi health and logistics sources. It does not replace a scholar for illness, menstruation, fidyah, missed manasik, disputes between madhhabs, or complicated travel restrictions.","items":["Qur\'anic anchors used here: 3:97, 2:158, 2:196, 2:203, 2:127.","Hadith anchors used here: Bukhari 1524, Ibn Majah 3015, Muslim 1327, Nasa\'i 3062, Nasa\'i 2622.","Official operational guidance: Nusuk, Saudi Ministry of Health, and Saudi Ministry of Hajj and Umrah."],"warningTitle":"Important note","warningText":"This page provides a mainstream structure and source trail, not a personalized fatwa. For personal cases, consult a qualified scholar. Verified sources like IslamQA or official authorities can provide reliable guidance."},"closing":{"arabic":"رَبَّنَا تَقَبَّلْ مِنَّا ۖ إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ","translation":"Our Lord, accept this from us. You are the All-Hearing, the All-Knowing.","reference":"Qur\'an 2:127","message":"May Allah grant every pilgrim a sound journey, a valid pilgrimage, and a return marked by humility, gratitude, and firmer obedience."}}')}}]);